import React, { useState } from 'react';
import { ChatPanel } from './ChatPanel';
import { NotesPanel } from './NotesPanel';
import { ParticipantsPanel } from './ParticipantsPanel';
import { WhiteboardPanel } from './WhiteboardPanel';

export const SidePanel = ({
  activePanel,
  setActivePanel,
  messages,
  onSendMessage,
  roomId,
  companion,
  userId,
  onStopAI,
  startListening,
  stopListening,
  isListening,
  participants,
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handlePanelSwitch = (panel) => {
    setActivePanel(panel);
    setIsMenuOpen(false);
  };

  const handleClosePanel = () => {
    setActivePanel('chat');
  };

  return (
    <div className="h-full flex flex-col bg-gray-900 relative">
      {/* Header with 3-dot menu and close button */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-700 bg-gray-800">
        <h3 className="text-lg font-semibold text-white">
          {activePanel === 'chat' && '💬 Chat'}
          {activePanel === 'participants' && '👥 Participants'}
          {activePanel === 'notes' && '📝 Notes'}
          {activePanel === 'whiteboard' && '🎨 Whiteboard'}
        </h3>

        <div className="flex items-center gap-2">
          {/* 3-dot menu */}
          <button
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="p-2 hover:bg-gray-700 rounded-lg transition-colors relative"
          >
            <svg
              className="w-5 h-5 text-gray-300"
              fill="currentColor"
              viewBox="0 0 20 20"
            >
              <circle cx="10" cy="5" r="1.5" />
              <circle cx="10" cy="10" r="1.5" />
              <circle cx="10" cy="15" r="1.5" />
            </svg>
          </button>

          {/* Close button (only show if not on chat) */}
          {activePanel !== 'chat' && (
            <button
              onClick={handleClosePanel}
              className="p-2 hover:bg-gray-700 rounded-lg transition-colors"
            >
              <svg
                className="w-5 h-5 text-gray-300"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M6 18L18 6M6 6l12 12"
                />
              </svg>
            </button>
          )}
        </div>

        {/* Dropdown menu */}
        {isMenuOpen && (
          <div className="absolute top-14 right-4 w-56 bg-gray-800 rounded-lg shadow-2xl border border-gray-700 py-2 z-50">
            <button
              onClick={() => handlePanelSwitch('chat')}
              className={`w-full px-4 py-2 text-left transition-colors ${
                activePanel === 'chat'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-300 hover:bg-gray-700'
              }`}
            >
              💬 Chat
            </button>
            <button
              onClick={() => handlePanelSwitch('participants')}
              className={`w-full px-4 py-2 text-left transition-colors ${
                activePanel === 'participants'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-300 hover:bg-gray-700'
              }`}
            >
              👥 Participants ({participants.length})
            </button>
            <button
              onClick={() => handlePanelSwitch('notes')}
              className={`w-full px-4 py-2 text-left transition-colors ${
                activePanel === 'notes'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-300 hover:bg-gray-700'
              }`}
            >
              📝 Notes
            </button>
            <button
              onClick={() => handlePanelSwitch('whiteboard')}
              className={`w-full px-4 py-2 text-left transition-colors ${
                activePanel === 'whiteboard'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-300 hover:bg-gray-700'
              }`}
            >
              🎨 Whiteboard
            </button>
          </div>
        )}
      </div>

      {/* Panel Content */}
      <div className="flex-1 overflow-hidden">
        {activePanel === 'chat' && (
          <ChatPanel
            companion={companion}
            messages={messages}
            onSendMessage={onSendMessage}
            onStopAI={onStopAI}
            isListening={isListening}
            startListening={startListening}
            stopListening={stopListening}
          />
        )}

        {activePanel === 'participants' && (
          <ParticipantsPanel participants={participants} />
        )}

        {activePanel === 'notes' && <NotesPanel roomId={roomId} />}

        {activePanel === 'whiteboard' && <WhiteboardPanel roomId={roomId} />}
      </div>
    </div>
  );
};

export default SidePanel;
